index 77470f8..06f75d2 100644
--- a/src/session-store.ts
+++ b/src/session-store.ts
@@ -1,3 +1,4 @@
+import { createHmac, randomUUID } from "crypto";
 import { pool } from "./pool.ts";

 export interface Session {
@@ -6,16 +7,56 @@ export interface Session {
   revokedAt: Date | null;
 }

-export const loadSession = async (id: string): Promise<Session | null> => {
+const SECRET = process.env.SESSION_SECRET || "dev-secret";
+
+const sign = (payload: object): string => {
+  const json = JSON.stringify(payload);
+  const sig = createHmac("sha256", SECRET).update(json).digest("hex");
+  return `${Buffer.from(json).toString("base64")}.${sig}`;
+};
+
+const verify = (token: string): object | null => {
+  const [encoded, sig] = token.split(".");
+  if (!encoded || !sig) return null;
+  try {
+    const json = Buffer.from(encoded, "base64").toString("utf8");
+    const expectedSig = createHmac("sha256", SECRET).update(json).digest("hex");
+    if (sig !== expectedSig) return null;
+    return JSON.parse(json);
+  } catch {
+    return null;
+  }
+};
+
+export const createSession = async (userId: string): Promise<string> => {
+  const sessionId = randomUUID();
+  const token = sign({ id: sessionId, userId });
+  await pool.query(
+    "INSERT INTO sessions (id, user_id) VALUES ($1, $2)",
+    [sessionId, userId]
+  );
+  return token;
+};
+
+export const loadSession = async (token: string): Promise<Session | null> => {
+  const payload = verify(token) as any;
+  if (!payload || !payload.id || !payload.userId) return null;
+
   const result = await pool.query(
     "SELECT id, user_id, revoked_at FROM sessions WHERE id = $1",
-    [id],
+    [payload.id]
   );
   const row = result.rows[0];
   if (row === undefined || row.revoked_at !== null) return null;
   return { id: row.id, userId: row.user_id, revokedAt: row.revoked_at };
 };

+export const validateSessionToken = (token: string): { id: string; userId: string } | null => {
+  const payload = verify(token) as any;
+  if (!payload || !payload.id || !payload.userId) return null;
+  return { id: payload.id, userId: payload.userId };
+};
+
 export const revokeSession = async (id: string): Promise<void> => {
   await pool.query("UPDATE sessions SET revoked_at = now() WHERE id = $1", [id]);
 };
